using System; // Exercise exact reaction deadlines and meaningful malformed-state failures.
using System.Collections.Generic; // Check that seeded freeze durations vary without unbounded state.
using System.Diagnostics; // Record new-system costs separately from movement-only benchmarks.
using System.Globalization; // Keep benchmark text portable.
using System.IO; // Load independently produced previous-release reference saves.
using Outbreak.Contracts; // Inspect actual persisted actor values.
using Outbreak.Core; // Exercise production human behavior and clock scheduling.
using Outbreak.Persistence; // Compare real serialized save continuations.
public static partial class Program // Extend the existing acceptance entry point without a second test runner.
{ // Begin human-reaction acceptance cases.
    private static void CheckHumanReactionCases() // Keep the new milestone's behavior checks together.
    { // Begin executed scenarios.
        Check("Human bravery yields fight, freeze and flight", () => // Exercise real decisions rather than only the margin formula.
        { // Begin the three controlled scenarios.
            foreach (HumanReaction response in new[] { HumanReaction.Fight, HumanReaction.Freeze, HumanReaction.Flight }) { World world = EncounterScenarios.HumanResponse(response); Run(world, 1); ActorState human = world.ActorAt(0); Require(world.HumanReactions && human.reaction == response && human.stress == (response == HumanReaction.Fight ? 43 : 2), "Natural bravery failed to produce " + response); Require(response != HumanReaction.Fight || human.x > 5, "Fighting human did not approach."); Require(response != HumanReaction.Flight || human.x < 5, "Fleeing human did not retreat."); Require(response != HumanReaction.Freeze || (human.x == 5 && human.y == 5 && human.freezeUntilTick > world.Tick), "Frozen human moved or lacked a deadline."); Inspect(world); } // Pin visible actions for every threshold outcome.
        }); // Finish reaction classification acceptance.
        Check("Human awareness, stress labels and recovery", () => // Separate distant observation from immediate flight.
        { // Begin awareness and stress fixtures.
            World world = new World(new WorldMap(30, 1), 8, 1000, true); int id; world.TrySpawn(Species.Human, 2, 0, out id); world.TrySpawn(Species.Zombie, 12, 0, out id); Run(world, 1); Require(world.ActorAt(0).reaction == HumanReaction.Aware && world.ActorAt(0).x == 2, "Distant threat caused immediate automatic flight."); // Aware watches before a close threat requires a courage response.
            SaveDocument saved = world.Capture(); saved.actors[1].x = 29; saved.actors[0].stress = 100; world = World.Restore(saved); Run(world, 5); Require(world.ActorAt(0).stress == 98 && world.ActorAt(0).reaction == HumanReaction.Aware, "Stress failed to recover without a visible threat."); // Use an actually out-of-range zombie rather than hiding a global count.
            Require(HumanRules.Level(0) == StressLevel.Normal && HumanRules.Level(1) == StressLevel.Aware && HumanRules.Level(21) == StressLevel.Cautious && HumanRules.Level(41) == StressLevel.Alarmed && HumanRules.Level(61) == StressLevel.Afraid && HumanRules.Level(81) == StressLevel.Panicked, "Six stress labels changed."); // Keep intensity independent from the chosen reaction.
        }); // Finish awareness and recovery acceptance.
        Check("Visible ally support is cached and cowards contribute at most minus one", () => // Demonstrate social influence and delayed observation of departures.
        { // Begin support fixtures.
            World world = EncounterScenarios.HumanResponse(HumanReaction.Flight, true); Run(world, 1); Require(world.ActorAt(0).groupSupport == 6 && world.ActorAt(0).reaction == HumanReaction.Aware, "Brave visible allies did not support a fearful human."); SaveDocument saved = world.Capture(); saved.actors[1].x = 1; saved.actors[1].y = 1; saved.actors[2].x = 12; saved.actors[2].y = 1; world = World.Restore(saved); Run(world, 5); Require(world.ActorAt(0).groupSupport == 6, "Ally departures were noticed instantly."); Run(world, 5); Require(world.ActorAt(0).groupSupport <= 0, "Support never refreshed after departures."); // Observe support only at the saved two-second interval.
            world = EncounterScenarios.HumanResponse(HumanReaction.Freeze, true); saved = world.Capture(); saved.actors[1].bravery = -3; saved.actors[2].bravery = -3; world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(0).groupSupport == -2, "Cowards subtracted more than one each."); // Each ally contributes its own bounded modifier.
            WorldMap map = new WorldMap(10, 10); for (int y = 0; y < 10; y++) map.Set(4, y, Terrain.Wall); world = new World(map, 1, 1000, true); int id; world.TrySpawn(Species.Human, 5, 5, out id); world.TrySpawn(Species.Human, 3, 5, out id); world.TrySpawn(Species.Zombie, 8, 5, out id); saved = world.Capture(); saved.actors[1].bravery = 3; world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(0).groupSupport == 0, "Support propagated through a solid wall."); // Range alone cannot make an ally visible.
        }); // Finish support acceptance.
        Check("Freeze varies, pauses, resolves once and resumes exactly", () => // Preserve the named reaction random stream and the original duration.
        { // Begin freeze timing acceptance.
            World world = EncounterScenarios.HumanResponse(HumanReaction.Freeze); Run(world, 1); ActorState human = world.ActorAt(0); long deadline = human.freezeUntilTick; Require(deadline - world.Tick >= HumanRules.MinFreezeTicks && deadline - world.Tick <= HumanRules.MaxFreezeTicks, "Freeze duration out of range."); string before = State(world); TickClock clock = new TickClock(); clock.Advance(500, world.Step); Require(State(world) == before, "Paused freeze or stress advanced."); World restored = Documents.ParseSave(before); Run(world, (int)(deadline - world.Tick)); Run(restored, (int)(deadline - restored.Tick)); Require(world.ActorAt(0).freezeResolved && world.ActorAt(0).freezeUntilTick == 0 && world.ActorAt(0).reaction != HumanReaction.Freeze, "Freeze renewed instead of resolving."); Require(State(world) == State(restored), "Freeze continuation diverged."); Run(world, 100); Run(restored, 100); Require(State(world) == State(restored), "Named reaction random stream was not restored."); // Continue through later stress, flight and possible conversion.
            HashSet<long> durations = new HashSet<long>(); for (uint seed = 1; seed <= 8; seed++) { World sample = new World(new WorldMap(12, 1), seed, 1000, true); int id; sample.TrySpawn(Species.Human, 3, 0, out id); sample.TrySpawn(Species.Zombie, 7, 0, out id); Run(sample, 1); durations.Add(sample.ActorAt(0).freezeUntilTick - sample.Tick); } Require(durations.Count > 1, "Freeze duration did not vary across seeds."); // Variable duration remains reproducible rather than using wall-time randomness.
        }); // Finish freeze acceptance.
        Check("Fight shoves nonlethally with cooldown, stagger and solid collision", () => // Give fighting a real bounded defense while preserving later zombie attack opportunities.
        { // Begin contact defense fixture.
            World world = new World(new WorldMap(2, 1), 5, 1000, true); int id; world.TrySpawn(Species.Human, 0, 0, out id); world.TrySpawn(Species.Zombie, 1, 0, out id); SaveDocument saved = world.Capture(); saved.actors[0].bravery = 3; world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(0).reaction == HumanReaction.Fight && world.ActorAt(1).staggerUntilTick == 4 && world.ActorAt(1).x == 1 && world.ActorAt(1).health == 100, "Defensive shove crossed the edge or damaged the durable zombie."); World restored = Documents.ParseSave(State(world)); Run(world, 1); Run(restored, 1); Require(world.ActorAt(0).turnAtTick == 0, "Staggered zombie attacked."); Run(world, 2); Run(restored, 2); Require(world.ActorAt(1).staggerUntilTick == 0, "Stagger did not expire exactly."); Run(world, 3); Run(restored, 3); Require(world.ActorAt(0).turnAtTick > 0 && State(world) == State(restored), "Shove cooldown prevented every future bite or failed save continuation."); Inspect(world); // A blocked push must not renew every human opportunity and permanently disable the zombie.
            world = new World(new WorldMap(4, 1), 5, 1000, true); world.TrySpawn(Species.Human, 1, 0, out id); world.TrySpawn(Species.Zombie, 2, 0, out id); saved = world.Capture(); saved.actors[0].bravery = 3; world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(1).x == 3, "Open-cell shove did not displace the zombie."); Inspect(world); // Verify occupancy after real displacement separately from blocked contact.
        }); // Finish defensive action acceptance.
        Check("Infection conversion clears human reaction state", () => // Keep zombie records canonical after an infected human turns.
        { // Begin conversion cleanup fixture.
            World world = EncounterScenarios.HumanResponse(HumanReaction.Flight); SaveDocument saved = world.Capture(); saved.actors[0].turnAtTick = 1; saved.actors[0].stress = 60; saved.actors[0].reaction = HumanReaction.Flight; saved.actors[0].groupSupport = 2; saved.actors[0].supportUntilTick = 5; world = World.Restore(saved); Run(world, 1); ActorState turned = world.ActorAt(0); Require(turned.species == Species.Zombie && turned.stress == 0 && turned.reaction == HumanReaction.Calm && turned.groupSupport == 0 && turned.supportUntilTick == 0, "Turning retained stale human decision state."); Require(State(Documents.ParseSave(State(world))) == State(world), "Converted actor failed save validation."); // Validate actual converted records through persistence.
        }); // Finish conversion cleanup acceptance.
        Check("Reaction save validation rejects corrupt state without changing the live world", () => // Fail closed on every new authoritative boundary.
        { // Begin malformed reaction checks.
            World world = EncounterScenarios.HumanResponse(HumanReaction.Freeze); Run(world, 1); string before = State(world); SaveDocument saved = world.Capture(); saved.reactionRandomState = 0; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].stress = 101; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].reaction = (HumanReaction)99; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].groupSupport = 7; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].threatPressure = 4; Reject(() => World.Restore(saved)); // Refuse invalid stream, stress, enums and courage inputs.
            saved = world.Capture(); saved.actors[0].freezeUntilTick = world.Tick; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].freezeResolved = true; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].supportUntilTick = world.Tick + 11; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].staggerUntilTick = world.Tick + 1; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[1].stress = 1; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.rulesVersion = EncounterRules.MemoryVersion; Reject(() => World.Restore(saved)); Require(State(world) == before, "Rejected reaction load changed the live world."); // Refuse incompatible species, timing and rules without replacing the current instance.
        }); // Finish validation acceptance.
        Check("Prototype-two saves retain independently recorded continuation", () => // Protect the user-verified previous milestone from silent behavioral upgrades.
        { // Begin prior-release compatibility check.
            string fixtures = Path.Combine(AppContext.BaseDirectory, "Fixtures"); World world = Documents.ParseSave(File.ReadAllText(Path.Combine(fixtures, "encounter-v2-input.json"))); Require(world.PursuitMemory && !world.HumanReactions && world.Capture().rulesVersion == EncounterRules.MemoryVersion, "Old pursuit save silently gained human reactions."); Run(world, 100); World expected = Documents.ParseSave(File.ReadAllText(Path.Combine(fixtures, "encounter-v2-expected.json"))); Require(State(world) == State(expected), "Prior pursuit behavior drifted."); // The expected state was produced by commit 0ce70bd, not by the new implementation.
        }); // Finish previous-release compatibility.
        Check("All manual tick batches are exact and stay paused", () => // Cover the user's requested additional step controls at the scheduler boundary.
        { // Begin manual clock acceptance.
            TickClock clock = new TickClock(); World world = EncounterScenarios.HumanResponse(HumanReaction.Freeze); foreach (int batch in new[] { 1, 10, 50, 100, 600 }) { long before = world.Tick; clock.StepTicks(batch, world.Step); Require(world.Tick == before + batch && clock.Paused && clock.DebtSeconds == 0, "Manual batch skipped ticks or resumed playback."); } Reject(() => clock.StepTicks(0, world.Step)); Reject(() => clock.StepTicks(601, world.Step)); clock.SetPaused(false); long tick = world.Tick; bool rejected = false; try { clock.StepTicks(1, world.Step); } catch (InvalidOperationException) { rejected = true; } Require(rejected && world.Tick == tick, "Running clock accepted a manual step."); // Invalid commands must not partially advance authoritative time.
        }); // Finish tick batch acceptance.
        Check("Human reactions thousand-body save continuation", () => // Measure the new systems explicitly instead of reusing movement-only timings.
        { // Begin the new reaction soak.
            World world = new World(new WorldMap(1000, 1000), 942, 1000, true); int id; for (int i = 0; i < 1000; i++) world.TrySpawn(i % 4 == 0 ? Species.Zombie : Species.Human, 1 + i % 50, 1 + i / 50, out id); Stopwatch timer = Stopwatch.StartNew(); Run(world, 500); timer.Stop(); Inspect(world); World restored = Documents.ParseSave(State(world)); Run(world, 100); Run(restored, 100); Require(world.Count == 1000 && State(world) == State(restored), "Reaction soak lost bodies or diverged after save/load."); results.Add("REACTIONS BENCH 1000x1000, 1000 bodies, 500 ticks: " + timer.Elapsed.TotalMilliseconds.ToString("0.00", CultureInfo.InvariantCulture) + " ms; stress, support, reactions, shove, pursuit and infection enabled; rendering excluded."); // Keep the measured scope visible beside test evidence.
        }); // Finish reaction soak acceptance.
    } // Finish all new acceptance cases.
} // Finish reaction checks.
